import React from 'react';
import { Link } from 'react-router-dom';

// You can keep the featuredSpots array as it is, or update it with local images
const featuredSpots = [
    {
        name: 'Dassam Falls, Ranchi',
        image: 'https://www.tripsavvy.com/thmb/p4nF3Ple0F-t2rV2Z6S0v53ylF0=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/GettyImages-1163499645-31c5302f1a604e2891393a52e12e6b9c.jpg',
        link: '/explore',
    },
    {
        name: 'Netarhat, Latehar',
        image: 'https://www.tourmyindia.com/states/jharkhand/images/netarhat1-1.jpg',
        link: '/explore',
    },
    {
        name: 'Baidyanath Dham, Deoghar',
        image: 'https://www.deoghar.nic.in/wp-content/uploads/2021/04/08_04_2021_01.jpg',
        link: '/explore',
    },
];


const HomePage = () => {
    return (
        <>
            {/* Hero Section with new background image */}
            <div
                className="relative h-[calc(100vh-80px)] -mt-20 flex items-center justify-center text-white text-center bg-cover bg-center"
                style={{ backgroundImage: `url('https://images.unsplash.com/photo-1623630613222-351d7c17a435?q=80&w=1932&auto=format&fit=crop')` }}
            >
                <div className="absolute inset-0 bg-black opacity-50"></div>
                <div className="relative z-10 p-4">
                    <h1 className="text-5xl md:text-6xl font-extrabold mb-4 leading-tight">
                        Discover the Land of Forests
                    </h1>
                    <p className="text-lg md:text-xl max-w-2xl mx-auto mb-8">
                        Explore Jharkhand's breathtaking waterfalls, serene hills, and rich cultural heritage.
                    </p>
                    {/* This button now links to the /explore page */}
                    <Link to="/explore" className="bg-leaf-green text-white font-bold py-3 px-8 rounded-full text-lg hover:bg-forest-green transition duration-300 transform hover:scale-105">
                        Start Your Journey
                    </Link>
                </div>
            </div>

            {/* Featured Destinations Section */}
            <div className="container mx-auto px-4 py-16">
                <h2 className="text-4xl font-bold text-center text-stone-gray mb-10">Featured Destinations</h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    {featuredSpots.map((spot) => (
                        <div key={spot.name} className="bg-white rounded-xl shadow-lg overflow-hidden transform hover:-translate-y-2 transition-transform duration-300">
                            <img src={spot.image} alt={spot.name} className="w-full h-56 object-cover" />
                            <div className="p-6">
                                <h3 className="text-xl font-semibold text-forest-green">{spot.name}</h3>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </>
    );
};

export default HomePage;
